"use strict";(globalThis.webpackChunkgrc||=[]).push([[12098],{61952(e){e.exports=JSON.parse('{"citeKey":"sun2007qualityservice","slug":"sun-2007-quality-service-10c1","title":"Quality of Service of Grid Computing: Resource Sharing","authors":["X.-H. Sun","M. Wu"],"venue":"The 6th International Conference on Grid and Cooperative Computing(GCC\'07)","type":"Conference","entryType":"inproceedings","date":"August, 2007","year":2007,"era":"iit","month":8,"doi":"10.1109/gcc.2007.102","abstract":"Rapid advancement of communication technology has changed the landscape of computing. New models of computing, such as business-on-demand, Web services, peer-to-peer networks, and Grid computing have emerged to harness distributed computing and network resources to provide powerful services. The non-deterministic characteristic of the resource availability in these new computing platforms raises an outstanding challenge: how to support Quality of Service (QoS) to meet a user\'s demand? In this study, we conduct a thorough study of QoS of distributed computing, especially on Grid computing where the requirement of distributed sharing and coordination goes to the extreme. We start at QoS policies, and then focus on technical issues of the enforcement of the policies and performance optimization under each policy. This study provides a classification of existing software system based on their underlying policies, a systematic understanding of QoS, and a framework for QoS of Grid computing.","hasAbstract":true,"lede":"Rapid advancement of communication technology has changed the landscape of computing.","links":{"pdf":"https://grc.iit.edu/papers/2007/sun-2007-quality-service-10c1.pdf"},"_projectIds":[],"grcSelected":false,"status":"published","visibility":"public","projectIds":[],"memberAuthors":["sun-xian-he"]}')}}]);